<template><main class="screen"><header><RouterLink to="/dashboard">‹</RouterLink><b>Invités</b><span class="plus">＋</span></header><input class="search" placeholder="⌕  Rechercher un invité"><div class="summary"><article><span>♙ Invités</span><strong>120</strong></article><article class="green"><span>♧ Confirmés</span><strong>85</strong></article><article class="orange"><span>♙ En attente</span><strong>20</strong></article><article class="red"><span>♙ Refusés</span><strong>15</strong></article></div><div v-for="g in guests" :key="g.name" class="guest"><span class="avatar">{{g.avatar}}</span><b>{{g.name}}</b><em :class="g.status">{{g.status==='confirm'?'Confirmé':g.status==='wait'?'En attente':'Refusé'}}</em><i>⋮</i></div><Nav/></main></template><script setup>const guests=[{name:'Aicha Diop',status:'confirm',avatar:'👩🏾'},{name:'Samuel Kouassi',status:'wait',avatar:'👨🏾'},{name:'Marie Lemoine',status:'confirm',avatar:'👩🏻'},{name:'Jean Dupont',status:'refuse',avatar:'👨🏻'}]</script><style scoped>.plus{font-size:15px}.summary{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin:8px 0}.summary article{padding:7px 8px;background:#fff4f6;border-radius:7px;font-size:6px}.summary article span{color:#8a777c}.summary strong{display:block;font-size:13px;margin-top:3px}.summary .green{background:#f1faf3}.summary .green strong{color:#3e9b5e}.summary .orange{background:#fff8ec}.summary .orange strong{color:#d68a1b}.summary .red{background:#fff1f4}.summary .red strong{color:#dc4b70}.guest{height:39px;border-bottom:1px solid #f0e8e8;display:flex;align-items:center;gap:6px;font-size:6.5px}.guest b{flex:1}.guest .avatar{font-size:13px}.guest em{font-style:normal;padding:3px 6px;border-radius:7px;font-size:5.5px}.confirm{color:#4c9b61;background:#f0faf2}.wait{color:#d88a1d;background:#fff5df}.refuse{color:#db4770;background:#fff0f4}.guest i{font-style:normal;font-size:10px}</style>